function greet(name) {
  return `Hello, ${name}`;
}

console.log(greet("Ana")); // "Hello, Ana"

// name -- the parameter (placeholder)
// "Ana" -- the argument (actual value passed in)

function greet(name = "friend") {
  return `Hello, ${name}`;
}

console.log(greet());      // "Hello, friend"
console.log(greet("Ana")); // "Hello, Ana"

// Declaration -- hoisted, callable earlier in the file
function add(a, b) {
  return a + b;
}

// Expression -- a function stored in a variable, not hoisted
const subtract = function (a, b) {
  return a - b;
};

function logOnly(message) {
  console.log(message);
  // no return statement
}

const result = logOnly("hi"); // logs "hi"
console.log(result);          // undefined
